    public bool enqueue(int x, int qn) {
        if (isFull(front, rear, qn, n, k))
            return false;

        int baseIndex = qn * (n / k);
        if (isEmpty(front, qn))
            front[qn] = baseIndex;

        rear[qn] = (rear[qn] == -1) ?
            baseIndex :
            baseIndex + (rear[qn] + 1 - baseIndex) % (n / k);
        arr[rear[qn]] = x;

        return true;
    }

